#!/usr/bin/env node
// Collect the desktop's per-slice modules so a new slice only adds files
// (hub #3000). Writes four generated files:
//
//   src/actions/index.generated.ts    every `export const SLICE` in src/actions/*.ts
//                                     (pure: actions, rules, keys, : commands)
//   src/actions/runtime.generated.ts  every `export const RUNTIME` in src/actions/*.ts
//                                     (DOM: run, snapshot, init)
//   src-tauri/src/handlers.generated.rs  the Tauri invoke handler: every
//                                     `#[tauri::command]` fn in src-tauri/src/*.rs
//   src-tauri/src/modules.generated.rs   the `pub mod <file>;` list: every
//                                     module file in src-tauri/src/*.rs (#181)
//
//   node scripts/slices.mjs           write them (part of `npm run build`, so of
//                                     `npm test`; src-tauri/build.rs runs it too);
//                                     exit 1 when a Tauri command name is defined twice
//   node scripts/slices.mjs --check   also exit 1 when one is missing or stale
//
// The outputs are build products, not committed (#60, desktop/.gitignore): two
// slices that each add a module touch no shared file, so they merge cleanly and
// the next build regenerates the registration from the merged sources.
//
// Node built-ins only; runs the same on macOS, Linux and Windows.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const desktopDir = resolve(dirname(fileURLToPath(import.meta.url)), '..');

const TS_HEADER = (what) => [
  `// GENERATED by \`node scripts/slices.mjs\` from every \`export const ${what}\` in`,
  '// src/actions/*.ts. Not committed (desktop/.gitignore); do not edit: add or',
  '// rename a slice module and run `npm run build`, which rewrites this file.',
  '// How a slice registers: desktop/README.md.',
];

/** `detail-spec.ts` -> `detail_spec` (an import alias). */
export function aliasOf(file) {
  return file.replace(/\.ts$/, '').replace(/[^A-Za-z0-9_]/g, '_');
}

/** The src/actions/*.ts files (sorted bytewise) that export `name`. */
export function exporters(files, name) {
  const re = new RegExp(`^export const ${name}\\b`, 'm');
  return files
    .filter(({ file }) => file.endsWith('.ts') && !file.endsWith('.generated.ts') && !file.endsWith('.d.ts'))
    .filter(({ text }) => re.test(text))
    .map(({ file }) => file)
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
}

export function renderIndex(sliceFiles) {
  const lines = [...TS_HEADER('SLICE'), "import type { SliceSpec } from '../registry.js';"];
  for (const f of sliceFiles) lines.push(`import { SLICE as ${aliasOf(f)} } from './${f.replace(/\.ts$/, '.js')}';`);
  lines.push('');
  lines.push('type IdsOf<S> = S extends SliceSpec<infer Id> ? Id : never;');
  lines.push('');
  lines.push('/** The action ids the slices add (registry.ts: ActionId = CoreActionId | SliceActionId). */');
  if (sliceFiles.length === 0) lines.push('export type SliceActionId = never;');
  else {
    lines.push('export type SliceActionId =');
    sliceFiles.forEach((f, i) => lines.push(`  | IdsOf<typeof ${aliasOf(f)}>${i === sliceFiles.length - 1 ? ';' : ''}`));
  }
  lines.push('');
  lines.push('/** Every slice in registry order: SliceSpec.order, then file name. */');
  lines.push('export const SLICES: readonly SliceSpec[] = [');
  for (const f of sliceFiles) lines.push(`  ${aliasOf(f)},`);
  lines.push('].sort((a, b) => a.order - b.order);');
  return `${lines.join('\n')}\n`;
}

export function renderRuntime(runtimeFiles) {
  const lines = [...TS_HEADER('RUNTIME'), "import type { SliceRuntime } from '../commands.js';"];
  for (const f of runtimeFiles) lines.push(`import { RUNTIME as ${aliasOf(f)} } from './${f.replace(/\.ts$/, '.js')}';`);
  lines.push('');
  lines.push('/** The DOM side of every slice, in file order (a function: the modules import commands.ts). */');
  lines.push('export function sliceRuntimes(): readonly SliceRuntime[] {');
  lines.push(`  return [${runtimeFiles.map(aliasOf).join(', ')}];`);
  lines.push('}');
  return `${lines.join('\n')}\n`;
}

/**
 * The `#[tauri::command]` fns of one Rust source: the name of the first `fn`
 * after each attribute (doc comments and other attributes may sit between).
 */
export function tauriCommands(text) {
  const out = [];
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    if (!/^\s*#\[tauri::command(\(.*\))?\]\s*$/.test(lines[i])) continue;
    for (let j = i + 1; j < lines.length; j++) {
      const m = /^\s*(?:pub(?:\([^)]*\))?\s+)?(?:async\s+)?fn\s+([A-Za-z_][A-Za-z0-9_]*)/.exec(lines[j]);
      if (m) { out.push(m[1]); break; }
      if (!/^\s*(#\[|\/\/)/.test(lines[j]) && lines[j].trim() !== '') {
        throw new Error(`#[tauri::command] on line ${i + 1} is not followed by a fn`);
      }
    }
  }
  return out;
}

/** The handler paths for every Rust source; lib.rs commands are crate-root names. */
export function handlerPaths(sources) {
  const paths = [];
  const seen = new Map();
  const files = [...sources].sort((a, b) => (a.file === 'lib.rs' ? -1 : b.file === 'lib.rs' ? 1 : a.file < b.file ? -1 : a.file > b.file ? 1 : 0));
  for (const { file, text } of files) {
    if (file === 'main.rs') continue;
    const mod = file === 'lib.rs' ? null : file.replace(/\.rs$/, '');
    for (const name of tauriCommands(text)) {
      if (seen.has(name)) {
        throw new Error(`Tauri command ${name} is defined in both ${seen.get(name)} and ${file}; the webview calls commands by bare name, so rename one`);
      }
      seen.set(name, file);
      paths.push(mod ? `${mod}::${name}` : name);
    }
  }
  return paths;
}

export function renderHandlers(paths) {
  return [
    '// GENERATED by `node scripts/slices.mjs` (in desktop/) from every',
    '// `#[tauri::command]` fn in src-tauri/src/*.rs. Not committed (desktop/.gitignore);',
    '// do not edit: add the command to its module; src-tauri/build.rs and',
    '// `npm run build` rewrite this file. lib.rs includes it as the invoke handler;',
    '// the module list is modules.generated.rs.',
    'tauri::generate_handler![',
    ...paths.map((p) => `    ${p},`),
    ']',
    '',
  ].join('\n');
}

/**
 * The Rust modules of src-tauri/src: every `*.rs` except the crate roots
 * (lib.rs, main.rs), the generated files and `*_tests.rs` (a module's test file,
 * pulled in with `#[path]` by its owner). Sorted bytewise.
 */
export function moduleNames(files) {
  return files
    .filter((f) => f.endsWith('.rs') && f !== 'lib.rs' && f !== 'main.rs' && !f.endsWith('.generated.rs') && !f.endsWith('_tests.rs'))
    .map((f) => f.replace(/\.rs$/, ''))
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
}

export function renderModules(names) {
  return [
    '// GENERATED by `node scripts/slices.mjs` (in desktop/) from every module file in',
    '// src-tauri/src/*.rs. Not committed (desktop/.gitignore); do not edit: add the',
    '// module file; src-tauri/build.rs and `npm run build` rewrite this file. lib.rs',
    '// includes it, so a new module needs no `pub mod` line there.',
    ...names.map((n) => `pub mod ${n};`),
    '',
  ].join('\n');
}

function readDir(dir, ext) {
  return readdirSync(dir).filter((f) => f.endsWith(ext) && !f.endsWith('.generated.rs')).map((file) => ({ file, text: readFileSync(join(dir, file), 'utf8') }));
}

export function generateAll(root = desktopDir) {
  const actionsDir = join(root, 'src/actions');
  const tauriDir = join(root, 'src-tauri/src');
  const ts = readDir(actionsDir, '.ts');
  return [
    { path: join(actionsDir, 'index.generated.ts'), text: renderIndex(exporters(ts, 'SLICE')) },
    { path: join(actionsDir, 'runtime.generated.ts'), text: renderRuntime(exporters(ts, 'RUNTIME')) },
    { path: join(tauriDir, 'modules.generated.rs'), text: renderModules(moduleNames(readdirSync(tauriDir))) },
    { path: join(tauriDir, 'handlers.generated.rs'), text: renderHandlers(handlerPaths(readDir(tauriDir, '.rs'))) },
  ];
}

function main() {
  const check = process.argv.includes('--check');
  const outs = generateAll();
  const stale = outs.filter((o) => (existsSync(o.path) ? readFileSync(o.path, 'utf8') : '') !== o.text);
  const rel = (p) => p.slice(desktopDir.length + 1);
  if (check) {
    if (stale.length) {
      console.error(`slices: stale ${stale.map((o) => rel(o.path)).join(', ')}. Run: node scripts/slices.mjs (or npm run build)`);
      process.exit(1);
    }
    console.log(`slices: ${outs.map((o) => rel(o.path)).join(', ')} are current`);
    return;
  }
  for (const o of stale) writeFileSync(o.path, o.text);
  console.log(`slices: ${stale.length ? `wrote ${stale.map((o) => rel(o.path)).join(', ')}` : 'generated files are current'}`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { main(); } catch (e) { console.error(`slices: ${e.message}`); process.exit(1); }
}
